import cgi
import http.server
import json
SUCCESS_RESPONSE = {
    'status': 'success',
    'message': 'Data received successfully.'
}
ERROR_RESPONSE = {
    'status': 'error',
    'message': 'Invalid data received.'
}
def task_func():
    class DataHandler(http.server.BaseHTTPRequestHandler):
        def do_POST(self):
            content_type = self.headers.get('Content-Type', '')
            if content_type != 'application/json':
                self.send_error_response(400, "Content-Type header is not application/json")
                return
            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length)
            try:
                data = json.loads(post_data)
            except json.JSONDecodeError:
                self.send_error_response(400, "Invalid JSON")
                return
            if 'data' not in data:
                self.send_error_response(400, "No data key in request")
                return
            self.send_response(200)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(SUCCESS_RESPONSE).encode())
        def send_error_response(self, code, message):
            self.send_response(code)
            self.send_header('Content-Type', 'application/json')
            self.end_headers()
            error_resp = ERROR_RESPONSE.copy()
            error_resp['message'] = message
            self.wfile.write(json.dumps(error_resp).encode())
    return DataHandler

